import{_ as o,o as n,c as t,a8 as i,aB as a,aC as l}from"./chunks/framework.ALLMRHJF.js";const b=JSON.parse('{"title":"Notification Banner","description":"","frontmatter":{},"headers":[],"relativePath":"content/plugins/bcew-plugin/user/notification-banner.md","filePath":"content/plugins/bcew-plugin/user/notification-banner.md"}'),r={name:"content/plugins/bcew-plugin/user/notification-banner.md"};function c(s,e,d,p,h,u){return n(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="notification-banner" tabindex="-1">Notification Banner <a class="header-anchor" href="#notification-banner" aria-label="Permalink to “Notification Banner”">​</a></h1><p>Use this tool to enable a Notification Banner at the top of each page of your website. You can choose the text shown in the banner, as well as its background color. HTML markup is also valid if you want to control the format of the text.</p><p>The tool lives in:</p><ul><li>WordPress Admin → Design System → Notification Banner</li></ul><p>Click Save Settings to apply changes, and see a preview below the Banner Preview label.</p><p><img src="'+a+'" alt="Notification Banner HOWTO"></p><h2 id="how-the-banner-tool-works" tabindex="-1">How the banner tool works <a class="header-anchor" href="#how-the-banner-tool-works" aria-label="Permalink to “How the banner tool works”">​</a></h2><ul><li>Enable/Disable the banner using the radio buttons.</li><li>The Banner Content textbox can accept plain text or HTML Markup, such as: <ul><li><strong>strong (bold)</strong></li><li><em>emphasis (italics)</em></li><li><u>underline (use with caution; can confuse links)</u></li><li><s>Strikethrough</s></li><li><mark>Highlighted text</mark></li><li><pre>preformatted text (preserves spaces and line breaks)</pre></li></ul></li><li>Other specialized text markup: <code>&lt;abbr&gt;</code>, <code>&lt;code&gt;</code>, <code>&lt;kbd&gt;</code>, <code>&lt;var&gt;</code>, <code>&lt;sup&gt;</code>, and <code>&lt;sub&gt;</code>.</li><li>List item markup: <code>&lt;ul&gt;</code>, <code>&lt;ol&gt;</code>, <code>&lt;li&gt;</code>, <code>&lt;dl&gt;</code>, <code>&lt;dt&gt;</code>, and <code>&lt;dd&gt;</code>.</li><li>Quotations and citations: <code>&lt;blockquote&gt;</code>, <code>&lt;q&gt;</code>, and <code>&lt;cite&gt;</code>.</li><li>Headings: <code>&lt;H1&gt;</code> through <code>&lt;H6&gt;</code>.</li><li>Choose the background banner color using the color-coded background status colors: <span style="background-color:#f8bb47;color:black;padding:3px;">Warning</span>, <span style="background-color:#ce3e39;color:white;padding:3px;">Danger</span>, <span style="background-color:#42814a;color:white;padding:3px;">Success</span>, or <span style="background-color:#053662;color:white;padding:3px;">Info</span>.</li><li>To hide the banner, simply click &#39;Disable&#39; beside &#39;Enable Banner&#39;.</li></ul><h2 id="notification-banner-recipes" tabindex="-1">Notification Banner recipes <a class="header-anchor" href="#notification-banner-recipes" aria-label="Permalink to “Notification Banner recipes”">​</a></h2><ul><li>Test Site Banner <ul><li>Text: <code>This is the Dev/Test Environment. The content you are viewing is not final and subject to change.</code></li><li>Background color: <span style="background-color:#ce3e39;color:white;padding:3px;">Danger</span></li></ul></li><li>Site under maintenance <ul><li>Text: <code>This site is under maintenance. Please check back periodically for updates</code></li><li>Background color: <span style="background-color:#f8bb47;color:black;padding:3px;">Warning</span></li></ul></li><li>Informational Banner <ul><li>Text: <code>Here are instructions for filling in this form...</code></li><li>Background color: <span style="background-color:#053662;color:white;padding:3px;">Info</span></li></ul></li></ul><h2 id="notification-banner-testing" tabindex="-1">Notification Banner testing <a class="header-anchor" href="#notification-banner-testing" aria-label="Permalink to “Notification Banner testing”">​</a></h2><ol><li>Save Settings.</li><li>Verify the banner preview matches expectations.</li><li>Navigate to your homepage and hard-refresh your browser.</li><li>Verify the text and background color of the banner are correct.</li></ol><p><img src="'+l+'" alt="Show Notification Banner"></p>',13)])])}const f=o(r,[["render",c]]);export{b as __pageData,f as default};
